def triples_sum_to_zero(l: list):
    n = len(l)
    if n < 3:
        return False

    l.sort()

    for i in range(n - 2):
        # Skip duplicate values for the first element to avoid redundant checks
        if i > 0 and l[i] == l[i - 1]:
            continue

        left = i + 1
        right = n - 1

        while left < right:
            current_sum = l[i] + l[left] + l[right]
            if current_sum == 0:
                return True
            elif current_sum < 0:
                left += 1
            else:
                right -= 1

    return False
```

