def minPath(grid, k):
    n = len(grid)
    # Locate the cell containing the value 1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                r, c = i, j
                break
        else:
            continue
        break

    path = [grid[r][c]]
    # Directions: up, down, left, right
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for _ in range(k - 1):
        best_val = None
        best_r, best_c = r, c
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                val = grid[nr][nc]
                if best_val is None or val < best_val:
                    best_val = val
                    best_r, best_c = nr, nc
        r, c = best_r, best_c
